mapper.select:
SELECT COUNT(*) FROM users u WHERE 1 = 1

    AND u.username LIKE CONCAT('%', #{username}, '%')


    AND u.real_name LIKE CONCAT('%', #{realName}, '%')


    AND u.type = #{type}


    AND u.dep_id = #{depId}

SELECT u.id, u.username, u.real_name AS realName, u.sex, u.phone, u.email, u.title,u.type, u.dep_id AS depId, COALESCE(d.name, '未分配院系') AS depName, u.hire_date AS hireDate, u.created_at AS createdAt, (SELECT COUNT(*) FROM assessments a WHERE a.user_id = u.id) AS assessmentCount, (SELECT MAX(a.overall_score) FROM assessments a WHERE a.user_id = u.id) AS latestAssessmentScore, (SELECT COUNT(*) FROM chat_sessions s WHERE s.user_id = u.id) AS simulationCount FROM users u LEFT JOIN departments d ON u.dep_id = d.id WHERE 1 = 1
AND u.username LIKE CONCAT('%', #{username}, '%')
AND u.real_name LIKE CONCAT('%', #{realName}, '%')
AND u.type = #{type}
AND u.dep_id = #{depId}
ORDER BY u.created_at DESC LIMIT #{offset}, #{pageSize}

SELECT
COUNT(DISTINCT u.id) AS teacherTotal,
COALESCE((
SELECT COUNT(*)
FROM assessments a
JOIN users ua ON a.user_id = ua.id


        ua.type = #{type}


        AND ua.dep_id = #{depId}


), 0) AS assessmentCount,
COALESCE((
SELECT COUNT(*)
FROM chat_sessions cs
JOIN users uc ON cs.user_id = uc.id


        uc.type = #{type}


        AND uc.dep_id = #{depId}


), 0) AS simulationCount,
COALESCE(ROUND((
SELECT AVG(a.overall_score)
FROM assessments a
JOIN users ub ON a.user_id = ub.id


        ub.type = #{type}


        AND ub.dep_id = #{depId}


), 2), 0) AS avgAssessmentScore
FROM users u


        u.type = #{type}


        AND u.dep_id = #{depId}

SELECT CASE u.type WHEN 0 THEN '教学型' WHEN 1 THEN '科研型' WHEN 2 THEN '综合型' ELSE '未知类型' END AS name, COUNT(*) AS value FROM users u
u.dep_id = #{depId}
GROUP BY u.type ORDER BY value DESC

SELECT COALESCE(d.name, '未分配院系') AS name, COUNT(*) AS value FROM users u LEFT JOIN departments d ON u.dep_id = d.id
u.type = #{type}
GROUP BY u.dep_id, d.name ORDER BY value DESC

SELECT CASE a.overall_level WHEN 0 THEN '优秀' WHEN 1 THEN '良好' WHEN 2 THEN '合格' WHEN 3 THEN '需改进' ELSE '未知' END AS name, COUNT(*) AS value FROM assessments a JOIN users u ON a.user_id = u.id
u.type = #{type}
AND u.dep_id = #{depId}
GROUP BY a.overall_level ORDER BY a.overall_level ASC

SELECT DATE_FORMAT(a.created_at, '%Y-%m') AS name, COUNT(*) AS value FROM assessments a JOIN users u ON a.user_id = u.id
a.created_at >= DATE_SUB(CURDATE(), INTERVAL 6 MONTH)
AND u.type = #{type}
AND u.dep_id = #{depId}
GROUP BY DATE_FORMAT(a.created_at, '%Y-%m') ORDER BY name ASC

SELECT DATE_FORMAT(u.created_at, '%Y-%m') AS name, COUNT(*) AS value FROM users u
u.created_at >= DATE_SUB(CURDATE(), INTERVAL 6 MONTH)
AND u.type = #{type}
AND u.dep_id = #{depId}
GROUP BY DATE_FORMAT(u.created_at, '%Y-%m') ORDER BY name ASC

SELECT COALESCE(d.name, '未分配院系') AS name, COUNT(cs.id) AS value FROM chat_sessions cs JOIN users u ON cs.user_id = u.id LEFT JOIN departments d ON u.dep_id = d.id
u.type = #{type}
AND u.dep_id = #{depId}
GROUP BY u.dep_id, d.name ORDER BY value DESC
